// ─── Notification sounds ─────────────────────────────────────────────────────
// Generates short tones via the Web Audio API — no audio files to host/cache.
// Ring sound uses an Audio element (data URI) to bypass AudioContext autoplay
// restrictions that silently block background sounds in Chrome/Safari.

let ctx = null
function getCtx() {
  if (!ctx) ctx = new (window.AudioContext || window.webkitAudioContext)()
  if (ctx.state === 'suspended') ctx.resume().catch(() => {})
  return ctx
}

function tone(freq, startTime, duration, gainCtx, type = 'sine', volume = 0.18) {
  const osc = gainCtx.createOscillator()
  const gain = gainCtx.createGain()
  osc.type = type
  osc.frequency.value = freq
  gain.gain.setValueAtTime(volume, startTime)
  gain.gain.exponentialRampToValueAtTime(0.0001, startTime + duration)
  osc.connect(gain)
  gain.connect(gainCtx.destination)
  osc.start(startTime)
  osc.stop(startTime + duration)
}

const PATTERNS = {
  message: [[880, 0, 0.10]],
  lead:    [[660, 0, 0.12], [990, 0.13, 0.16]],
  email:   [[740, 0, 0.10], [740, 0.14, 0.10]],
  huddle:  [[523, 0, 0.18], [659, 0.2, 0.18], [784, 0.4, 0.22]],
  call:    [[523, 0, 0.15], [392, 0.18, 0.15], [523, 0.36, 0.15], [392, 0.54, 0.15]],
  sms:     [[660, 0, 0.09], [880, 0.11, 0.09], [1046, 0.22, 0.12]],
  fax:     [[392, 0, 0.14], [392, 0.22, 0.14], [392, 0.44, 0.14]],
  reminder:[[587, 0, 0.16], [784, 0.18, 0.22]],
}

// ─── Ring audio element ───────────────────────────────────────────────────────
// Pre-built WAV as a data URI — no network request, works offline, bypasses
// AudioContext autoplay policy that silently blocks background Web Audio calls.
const RING_WAV = 'data:audio/wav;base64,'
let ringAudio = null
function getRingAudio() {
  if (!ringAudio) {
    ringAudio = new Audio(RING_WAV)
    ringAudio.loop = false
    ringAudio.volume = 0.7
  }
  return ringAudio
}

export function playRing() {
  if (!isSoundEnabled()) return
  // Create a fresh Audio element each time — avoids stale state
  // and sidesteps autoplay restrictions since the WAV is inline data
  try {
    const a = new Audio(RING_WAV)
    a.volume = 0.7
    a.play().catch(err => {
      console.warn('[playRing] Audio element blocked:', err)
      playSound('call')
    })
  } catch(err) {
    console.warn('[playRing] Error:', err)
    playSound('call')
  }
}

export function stopRingAudio() {
  if (ringAudio) {
    try { ringAudio.pause(); ringAudio.currentTime = 0 } catch(_) {}
  }
}

// ─── Autoplay-policy fix ─────────────────────────────────────────────────────
let primed = false
function primeOnce() {
  if (primed) return
  primed = true
  try {
    const c = getCtx()
    const buf = c.createBuffer(1, 1, 22050)
    const src = c.createBufferSource()
    src.buffer = buf
    src.connect(c.destination)
    src.start(0)
    // Also pre-load ring audio so it's ready to play instantly
    getRingAudio().load()
  } catch (_) {}
  window.removeEventListener('pointerdown', primeOnce)
  window.removeEventListener('keydown', primeOnce)
  window.removeEventListener('touchstart', primeOnce)
  window.removeEventListener('mousemove', primeOnce)
  window.removeEventListener('scroll', primeOnce)
}
if (typeof window !== 'undefined') {
  window.addEventListener('pointerdown', primeOnce)
  window.addEventListener('keydown', primeOnce)
  window.addEventListener('touchstart', primeOnce)
  window.addEventListener('mousemove', primeOnce, { once: true })
  window.addEventListener('scroll', primeOnce, { once: true })
}

export function isSoundEnabled() {
  return localStorage.getItem('tcr_sounds_enabled') !== 'off'
}

export function setSoundEnabled(on) {
  localStorage.setItem('tcr_sounds_enabled', on ? 'on' : 'off')
}

export function playSound(kind) {
  if (!isSoundEnabled()) return
  try {
    const audioCtx = getCtx()
    if (audioCtx.state === 'suspended') {
      audioCtx.resume().then(() => {
        try {
          const pattern = PATTERNS[kind] || PATTERNS.message
          const now = audioCtx.currentTime
          pattern.forEach(([freq, offset, dur]) => tone(freq, now + offset, dur, audioCtx))
        } catch (_) {}
      }).catch(() => {})
      return
    }
    const pattern = PATTERNS[kind] || PATTERNS.message
    const now = audioCtx.currentTime
    pattern.forEach(([freq, offset, dur]) => tone(freq, now + offset, dur, audioCtx))
  } catch (_) {}
}

// ─── Outbound ringback tone ───────────────────────────────────────────────────
// US standard ringback: 2s on, 4s off cycle using 440Hz + 480Hz tones.
// Played locally in the browser while waiting for the outbound call to connect.
let ringbackNodes = []
let ringbackInterval = null

export function playRingback() {
  stopRingback()
  try {
    const c = getCtx()
    if (c.state === 'suspended') c.resume()

    function startBurst() {
      const gain = c.createGain()
      gain.gain.setValueAtTime(0.18, c.currentTime)
      gain.connect(c.destination)

      const freqs = [440, 480]
      const nodes = freqs.map(f => {
        const osc = c.createOscillator()
        osc.type = 'sine'
        osc.frequency.value = f
        osc.connect(gain)
        osc.start()
        return osc
      })

      // Stop after 2s (on time)
      const stopAt = c.currentTime + 2
      gain.gain.setValueAtTime(0.18, stopAt - 0.05)
      gain.gain.linearRampToValueAtTime(0, stopAt)
      nodes.forEach(n => n.stop(stopAt + 0.05))
      ringbackNodes = [...ringbackNodes, ...nodes, gain]
    }

    startBurst()
    // Repeat every 6s (2s on, 4s off)
    ringbackInterval = setInterval(startBurst, 6000)
  } catch(e) {
    console.warn('[ringback] error:', e)
  }
}

export function stopRingback() {
  if (ringbackInterval) { clearInterval(ringbackInterval); ringbackInterval = null }
  ringbackNodes.forEach(n => { try { n.stop?.(); n.disconnect?.() } catch(_){} })
  ringbackNodes = []
}
